Brief:
A long brief for a canal boat game. The player steers a narrow wooden boat along a city canal at dusk, and the view scrolls upward so the canal keeps coming toward the boat. The boat sits in one of three channels, and the player drags a finger left or right to move it between them. Moored barges, low bridges and floating crates block the channels, and they arrive faster as the run goes on. Lanterns float between the obstacles; each lantern collected adds to the score, and a lantern that is missed simply drifts away. There is only one boat, so the first collision ends the run. Please make the water a deep teal, the barges a warm brown and the lanterns a soft orange, with thin white lines for the ripples. I would also like a gentle splash sound whenever a lantern is collected and a low horn when the boat hits something, if that is possible. During play, show the score in the top corner in a clear, readable font. At the end, show how many lanterns were collected, say what the boat hit, and offer a way to set off again. The first few seconds should be calm, with no obstacles at all, so a new player can learn to steer before anything arrives.

Plan:
{"gameType":"arcade-run","input":"drag-follow","lang":"en","loop":"Drag to steer your narrow boat between three canal channels, dodging barges, bridges and crates while collecting floating lanterns. One collision ends the run, so survive as long as you can and gather as many lanterns as possible.","slug":"canal-lanterns","style":"risograph","title":"Canal Lanterns"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Canal Lanterns</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #fbf7ee;
11|     overflow: hidden;
12|     touch-action: none;
13|     font-family: 'Arial Narrow', Arial, sans-serif;
14|   }
15|   #wrap {
16|     position: fixed; inset: 0;
17|     display: flex; align-items: center; justify-content: center;
18|     background: #fbf7ee;
19|   }
20|   canvas {
21|     display: block;
22|     touch-action: none;
23|     background: #fbf7ee;
24|   }
25|   #hint {
26|     position: absolute;
27|     pointer-events: none;
28|     color: #0078bf;
29|     font-weight: 900;
30|     letter-spacing: 1px;
31|     text-shadow: 1px 1px 0 #ff48b0;
32|   }
33| </style>
34| </head>
35| <body>
36| <div id="wrap">
37| <canvas id="game"></canvas>
38| </div>
39| <script>
40| // ---- Bridge helper (verbatim) ----
41| const CARTRIDGE = {
42|   send(type, payload = {}) {
43|     window.parent.postMessage(
44|       { source: "cartridge", v: 1, type, payload },
45|       "*",
46|     );
47|   },
48| };
49| </script>
50| <script>
51| (function(){
52|   const canvas = document.getElementById('game');
53|   const ctx = canvas.getContext('2d');
54| 
55|   // ---------- sizing ----------
56|   let W = 0, H = 0, DPR = 1;
57|   function resize(){
58|     DPR = window.devicePixelRatio || 1;
59|     W = window.innerWidth;
60|     H = window.innerHeight;
61|     canvas.width = Math.floor(W * DPR);
62|     canvas.height = Math.floor(H * DPR);
63|     canvas.style.width = W + 'px';
64|     canvas.style.height = H + 'px';
65|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
66|     buildGrain();
67|   }
68|   window.addEventListener('resize', resize);
69| 
70|   // ---------- grain tile (pre-rendered once) ----------
71|   let grainCanvas = null;
72|   function buildGrain(){
73|     const size = 128;
74|     grainCanvas = document.createElement('canvas');
75|     grainCanvas.width = size;
76|     grainCanvas.height = size;
77|     const gctx = grainCanvas.getContext('2d');
78|     const imgData = gctx.createImageData(size, size);
79|     for (let i = 0; i < imgData.data.length; i += 4) {
80|       const v = Math.random() * 255;
81|       imgData.data[i] = v;
82|       imgData.data[i+1] = v;
83|       imgData.data[i+2] = v;
84|       imgData.data[i+3] = 255;
85|     }
86|     gctx.putImageData(imgData, 0, 0);
87|   }
88| 
89|   function drawGrain(){
90|     if (!grainCanvas) return;
91|     ctx.save();
92|     ctx.globalAlpha = 0.08;
93|     const pat = ctx.createPattern(grainCanvas, 'repeat');
94|     ctx.fillStyle = pat;
95|     ctx.fillRect(0, 0, W, H);
96|     ctx.restore();
97|   }
98| 
99|   // ---------- palette ----------
100|   const PAPER = '#fbf7ee';
101|   const INK1 = '#ff48b0';
102|   const INK2 = '#0078bf';
103|   const OVER = '#5b3a8c';
104| 
105|   // ---------- game state ----------
106|   const LANES = 3;
107|   let laneX = [];
108|   function computeLanes(){
109|     const margin = W * 0.18;
110|     const usable = W - margin * 2;
111|     laneX = [];
112|     for (let i = 0; i < LANES; i++){
113|       laneX.push(margin + usable * (i + 0.5) / LANES);
114|     }
115|   }
116| 
117|   let last = 0;
118|   let running = false; // is a run in progress (post-start, pre-end)
119|   let started = false; // has start ever been sent for this run
120|   let paused = false;
121|   let score = 0;
122|   let scoreShown = -1;
123|   let gameTime = 0;
124|   let speed = 220; // px/sec scroll speed
125|   let boat = { x: 0, y: 0, targetX: 0, lane: 1, w: 0, h: 0 };
126|   let obstacles = [];
127|   let lanterns = [];
128|   let spawnTimer = 0;
129|   let lanternTimer = 0;
130|   let idleTimer = 0;
131|   let hasMoved = false;
132|   let bootSent = false;
133|   let firstFrameDrawn = false;
134|   let endSent = false;
135| 
136|   function toCanvas(evt){
137|     const rect = canvas.getBoundingClientRect();
138|     return {
139|       x: (evt.clientX - rect.left),
140|       y: (evt.clientY - rect.top)
141|     };
142|   }
143| 
144|   function resetState(){
145|     score = 0;
146|     scoreShown = -1;
147|     gameTime = 0;
148|     speed = 220;
149|     obstacles = [];
150|     lanterns = [];
151|     spawnTimer = 1.4; // fairness: first hazard well ahead
152|     lanternTimer = 0.8;
153|     idleTimer = 0;
154|     hasMoved = false;
155|     endSent = false;
156|     computeLanes();
157|     boat.lane = 1;
158|     boat.x = laneX[1];
159|     boat.targetX = laneX[1];
160|     boat.y = H * 0.78;
161|     boat.w = Math.min(W, H) * 0.09;
162|     boat.h = boat.w * 2.0;
163|   }
164| 
165|   function backToTitle(){
166|     running = false;
167|     started = false;
168|     paused = false;
169|     resetState();
170|   }
171| 
172|   function startRun(){
173|     if (running) return;
174|     resetState();
175|     running = true;
176|     started = true;
177|     CARTRIDGE.send('start', {});
178|   }
179| 
180|   // ---------- input ----------
181|   let held = false;
182|   canvas.addEventListener('pointerdown', (event) => {
183|     if (!started){
184|       startRun();
185|     }
186|     held = true;
187|     hasMoved = true;
188|     idleTimer = 0;
189|     try { canvas.setPointerCapture(event.pointerId); } catch(e){}
190|     const p = toCanvas(event);
191|     boat.targetX = clamp(p.x, boat.w, W - boat.w);
192|   });
193|   canvas.addEventListener('pointermove', (event) => {
194|     if (!held) return;
195|     hasMoved = true;
196|     idleTimer = 0;
197|     const p = toCanvas(event);
198|     boat.targetX = clamp(p.x, boat.w, W - boat.w);
199|   });
200|   function releasePointer(){ held = false; }
201|   canvas.addEventListener('pointerup', releasePointer);
202|   canvas.addEventListener('pointercancel', releasePointer);
203| 
204|   function clamp(v, lo, hi){
205|     return Math.max(lo, Math.min(hi, v));
206|   }
207| 
208|   // ---------- spawning ----------
209|   function spawnObstacle(){
210|     // pick 1 or 2 lanes blocked, leave at least one open
211|     const type = Math.random();
212|     const blockedCount = Math.random() < 0.6 ? 1 : 2;
213|     const lanesArr = [0,1,2];
214|     for (let i = lanesArr.length - 1; i > 0; i--){
215|       const j = Math.floor(Math.random() * (i+1));
216|       [lanesArr[i], lanesArr[j]] = [lanesArr[j], lanesArr[i]];
217|     }
218|     const blocked = lanesArr.slice(0, blockedCount);
219|     const kind = type < 0.5 ? 'barge' : (type < 0.8 ? 'bridge' : 'crate');
220|     for (const laneIdx of blocked){
221|       obstacles.push({
222|         lane: laneIdx,
223|         x: laneX[laneIdx],
224|         y: -100,
225|         w: Math.min(W,H) * (kind === 'bridge' ? 0.24 : 0.16),
226|         h: Math.min(W,H) * (kind === 'bridge' ? 0.14 : 0.12),
227|         kind: kind,
228|         passed: false
229|       });
230|     }
231|   }
232| 
233|   function spawnLantern(){
234|     const laneIdx = Math.floor(Math.random() * LANES);
235|     lanterns.push({
236|       lane: laneIdx,
237|       x: laneX[laneIdx],
238|       y: -60,
239|       r: Math.min(W,H) * 0.035,
240|       taken: false
241|     });
242|   }
243| 
244|   // ---------- update ----------
245|   function advance(dt){
246|     gameTime += dt;
247|     idleTimer += dt;
248|     speed += dt * 4.2; // ramp difficulty via speed
249| 
250|     // ease boat towards target
251|     boat.x += (boat.targetX - boat.x) * Math.min(1, dt * 10);
252| 
253|     // spawn timers
254|     spawnTimer -= dt;
255|     if (spawnTimer <= 0){
256|       spawnObstacle();
257|       spawnTimer = Math.max(0.55, 1.5 - gameTime * 0.01);
258|     }
259|     lanternTimer -= dt;
260|     if (lanternTimer <= 0){
261|       spawnLantern();
262|       lanternTimer = 0.9 + Math.random() * 0.9;
263|     }
264| 
265|     for (const o of obstacles){
266|       o.y += speed * dt;
267|     }
268|     obstacles = obstacles.filter(o => o.y < H + 150);
269| 
270|     for (const l of lanterns){
271|       l.y += speed * dt;
272|     }
273|     lanterns = lanterns.filter(l => l.y < H + 80 && !l.taken);
274|   }
275| 
276|   function collide(){
277|     for (const o of obstacles){
278|       const dx = Math.abs(o.x - boat.x);
279|       const dy = Math.abs(o.y - boat.y);
280|       if (dx < (o.w + boat.w) * 0.42 && dy < (o.h + boat.h) * 0.38){
281|         crash();
282|         return;
283|       }
284|     }
285|     for (const l of lanterns){
286|       if (l.taken) continue;
287|       const dx = l.x - boat.x;
288|       const dy = l.y - boat.y;
289|       const dist = Math.sqrt(dx*dx + dy*dy);
290|       if (dist < l.r + boat.w * 0.5){
291|         l.taken = true;
292|         score += 10;
293|         CARTRIDGE.send('score', { value: score });
294|       }
295|     }
296|   }
297| 
298|   function crash(){
299|     if (endSent) return;
300|     running = false;
301|     endSent = true;
302|     CARTRIDGE.send('end', { reason: 'lose', value: score });
303|   }
304| 
305|   // ---------- drawing ----------
306|   function drawWater(){
307|     ctx.fillStyle = PAPER;
308|     ctx.fillRect(0, 0, W, H);
309| 
310|     // canal channels (ink2 flat, offset stripes for misregistration)
311|     const margin = W * 0.18;
312|     const usable = W - margin * 2;
313|     ctx.save();
314|     ctx.globalAlpha = 0.18;
315|     ctx.fillStyle = INK2;
316|     ctx.fillRect(margin, 0, usable, H);
317|     ctx.restore();
318| 
319|     // lane divider lines with misregistration offset
320|     ctx.strokeStyle = INK2;
321|     ctx.lineWidth = 3;
322|     ctx.setLineDash([18, 14]);
323|     const scrollOffset = (gameTime * speed) % 32;
324|     for (let i = 1; i < LANES; i++){
325|       const x = margin + usable * i / LANES;
326|       ctx.save();
327|       ctx.translate(1, 1);
328|       ctx.strokeStyle = INK1;
329|       ctx.globalAlpha = 0.5;
330|       ctx.beginPath();
331|       ctx.moveTo(x, -scrollOffset);
332|       ctx.lineTo(x, H);
333|       ctx.stroke();
334|       ctx.restore();
335| 
336|       ctx.beginPath();
337|       ctx.moveTo(x, -scrollOffset);
338|       ctx.lineTo(x, H);
339|       ctx.stroke();
340|     }
341|     ctx.setLineDash([]);
342| 
343|     // canal edges
344|     ctx.fillStyle = INK1;
345|     ctx.fillRect(0, 0, margin, H);
346|     ctx.fillRect(W - margin, 0, margin, H);
347|   }
348| 
349|   function drawHalftoneCircle(x, y, r, color){
350|     ctx.save();
351|     ctx.fillStyle = color;
352|     ctx.beginPath();
353|     ctx.arc(x, y, r, 0, Math.PI * 2);
354|     ctx.fill();
355|     ctx.restore();
356|   }
357| 
358|   function drawBoat(){
359|     const x = boat.x, y = boat.y, w = boat.w, h = boat.h;
360|     // shadow ink2 offset
361|     ctx.save();
362|     ctx.translate(2, 2);
363|     ctx.fillStyle = INK2;
364|     ctx.globalAlpha = 0.55;
365|     drawHullPath(x, y, w, h);
366|     ctx.fill();
367|     ctx.restore();
368| 
369|     // main hull ink1
370|     ctx.fillStyle = INK1;
371|     drawHullPath(x, y, w, h);
372|     ctx.fill();
373| 
374|     // cabin (overlap color)
375|     ctx.fillStyle = OVER;
376|     ctx.fillRect(x - w*0.28, y - h*0.12, w*0.56, h*0.28);
377|   }
378| 
379|   function drawHullPath(x, y, w, h){
380|     ctx.beginPath();
381|     ctx.moveTo(x - w*0.5, y - h*0.3);
382|     ctx.lineTo(x + w*0.5, y - h*0.3);
383|     ctx.lineTo(x + w*0.4, y + h*0.45);
384|     ctx.quadraticCurveTo(x, y + h*0.65, x - w*0.4, y + h*0.45);
385|     ctx.closePath();
386|   }
387| 
388|   function drawObstacle(o){
389|     ctx.save();
390|     ctx.translate(1, 1);
391|     ctx.globalAlpha = 0.5;
392|     ctx.fillStyle = INK2;
393|     obstacleShape(o);
394|     ctx.restore();
395| 
396|     ctx.fillStyle = o.kind === 'bridge' ? OVER : INK2;
397|     obstacleShape(o);
398|   }
399| 
400|   function obstacleShape(o){
401|     ctx.beginPath();
402|     if (o.kind === 'bridge'){
403|       ctx.fillRect(o.x - o.w/2, o.y - o.h/2, o.w, o.h);
404|     } else if (o.kind === 'barge'){
405|       ctx.fillRect(o.x - o.w/2, o.y - o.h/2, o.w, o.h*0.8);
406|     } else {
407|       // crate: rotated square
408|       ctx.save();
409|       ctx.translate(o.x, o.y);
410|       ctx.rotate(Math.PI/4);
411|       ctx.fillRect(-o.w/2.6, -o.w/2.6, o.w/1.3, o.w/1.3);
412|       ctx.restore();
413|       return;
414|     }
415|   }
416| 
417|   function drawLantern(l){
418|     // glow ink1 offset
419|     ctx.save();
420|     ctx.translate(1, -1);
421|     ctx.globalAlpha = 0.5;
422|     drawHalftoneCircle(l.x, l.y, l.r, INK1);
423|     ctx.restore();
424| 
425|     drawHalftoneCircle(l.x, l.y, l.r, INK1);
426|     ctx.fillStyle = OVER;
427|     ctx.fillRect(l.x - l.r*0.15, l.y - l.r*1.4, l.r*0.3, l.r*0.6);
428|   }
429| 
430|   function drawHUD(){
431|     ctx.fillStyle = INK2;
432|     ctx.font = '900 ' + Math.round(Math.min(W,H)*0.055) + 'px Arial Narrow, Arial, sans-serif';
433|     ctx.textBaseline = 'top';
434|     ctx.save();
435|     ctx.translate(1,1);
436|     ctx.fillStyle = INK1;
437|     ctx.fillText('LANTERNS ' + score, 16, 14);
438|     ctx.restore();
439|     ctx.fillStyle = INK2;
440|     ctx.fillText('LANTERNS ' + score, 16, 14);
441|   }
442| 
443|   function drawTitle(){
444|     ctx.fillStyle = PAPER;
445|     ctx.fillRect(0, 0, W, H);
446|     drawWater();
447| 
448|     const t = gameTime;
449|     ctx.save();
450|     ctx.globalAlpha = 0.9;
451|     ctx.fillStyle = INK1;
452|     ctx.font = '900 ' + Math.round(Math.min(W,H)*0.09) + 'px Arial Narrow, Arial, sans-serif';
453|     ctx.textAlign = 'center';
454|     ctx.save();
455|     ctx.translate(2,2);
456|     ctx.fillStyle = INK2;
457|     ctx.fillText('CANAL LANTERNS', W/2, H*0.28);
458|     ctx.restore();
459|     ctx.fillStyle = INK1;
460|     ctx.fillText('CANAL LANTERNS', W/2, H*0.28);
461|     ctx.restore();
462| 
463|     const pulse = 0.6 + 0.4 * Math.sin(t * 3);
464|     ctx.save();
465|     ctx.globalAlpha = pulse;
466|     ctx.fillStyle = OVER;
467|     ctx.font = '700 ' + Math.round(Math.min(W,H)*0.04) + 'px Arial Narrow, Arial, sans-serif';
468|     ctx.textAlign = 'center';
469|     ctx.fillText('DRAG TO STEER YOUR BOAT', W/2, H*0.42);
470|     ctx.fillText('TAP OR DRAG TO BEGIN', W/2, H*0.48);
471|     ctx.restore();
472| 
473|     // idle floating boat preview
474|     boat.x = laneX[1] + Math.sin(t * 1.5) * W * 0.08;
475|     boat.y = H * 0.7;
476|     drawBoat();
477| 
478|     ctx.textAlign = 'left';
479|   }
480| 
481|   function drawGameOver(){
482|     ctx.save();
483|     ctx.fillStyle = PAPER;
484|     ctx.globalAlpha = 0.85;
485|     ctx.fillRect(0, 0, W, H);
486|     ctx.restore();
487| 
488|     ctx.textAlign = 'center';
489|     ctx.save();
490|     ctx.translate(2,2);
491|     ctx.fillStyle = INK2;
492|     ctx.font = '900 ' + Math.round(Math.min(W,H)*0.08) + 'px Arial Narrow, Arial, sans-serif';
493|     ctx.fillText('CAPSIZED', W/2, H*0.36);
494|     ctx.restore();
495|     ctx.fillStyle = INK1;
496|     ctx.fillText('CAPSIZED', W/2, H*0.36);
497| 
498|     ctx.font = '700 ' + Math.round(Math.min(W,H)*0.045) + 'px Arial Narrow, Arial, sans-serif';
499|     ctx.fillStyle = OVER;
500|     ctx.fillText('LANTERNS COLLECTED: ' + score, W/2, H*0.46);
501|     ctx.fillText('TAP TO SAIL AGAIN', W/2, H*0.54);
502|     ctx.textAlign = 'left';
503|   }
504| 
505|   function draw(){
506|     ctx.clearRect(0, 0, W, H);
507|     if (!started){
508|       drawTitle();
509|     } else if (running){
510|       drawWater();
511|       for (const l of lanterns) drawLantern(l);
512|       for (const o of obstacles) drawObstacle(o);
513|       drawBoat();
514|       drawHUD();
515|     } else {
516|       drawWater();
517|       for (const l of lanterns) drawLantern(l);
518|       for (const o of obstacles) drawObstacle(o);
519|       drawBoat();
520|       drawHUD();
521|       drawGameOver();
522|     }
523|     drawGrain();
524|     if (!firstFrameDrawn){
525|       firstFrameDrawn = true;
526|       if (!bootSent){
527|         bootSent = true;
528|         CARTRIDGE.send('boot', { title: 'Canal Lanterns', gameType: 'arcade-run', lang: 'en' });
529|       }
530|     }
531|   }
532| 
533|   // restart on tap after game over
534|   canvas.addEventListener('pointerdown', (event) => {
535|     if (started && !running){
536|       // after game over, restart
537|       startRun();
538|     }
539|   });
540| 
541|   // ---------- loop ----------
542|   function frame(now){
543|     const dt = Math.min((now - last) / 1000, 0.05);
544|     last = now;
545|     if (running && !paused){
546|       advance(dt || 0);
547|       collide();
548|     }
549|     draw();
550|     requestAnimationFrame(frame);
551|   }
552| 
553|   // ---------- host messages ----------
554|   window.addEventListener('message', (event) => {
555|     const data = event.data;
556|     if (!data || data.source !== 'cartridge-host') return;
557|     if (data.type === 'pause') paused = true;
558|     if (data.type === 'resume') paused = false;
559|     if (data.type === 'reset') backToTitle();
560|   });
561| 
562|   // ---------- init ----------
563|   resize();
564|   resetState();
565|   requestAnimationFrame((t) => { last = t; requestAnimationFrame(frame); });
566| })();
567| </script>
568| </body>
569| </html>
570|

